        "kind": "html",
        "table": null,
        "pk": null,
        "html": "<div style=\"background: linear-gradient(120deg, #0d4a4a 0%, #1a6b6b 55%, #1e8080 100%); padding: 16px 36px; display: flex; align-items: center; justify-content: space-between; position: relative; overflow: hidden; box-shadow: 0 6px 32px rgba(13,74,74,0.22); color: #ffffff; border-top-left-radius: 8px; border-top-right-radius: 8px;\">\n    <div style=\"position: absolute; width: 260px; height: 260px; background: rgba(255,255,255,0.04); border-radius: 50%; top: -80px; right: 120px; pointer-events: none;\"></div>\n    <div style=\"position: absolute; width: 160px; height: 160px; background: rgba(58,173,173,0.12); border-radius: 50%; bottom: -60px; right: 60px; pointer-events: none;\"></div>\n\n    <div style=\"display: flex; align-items: center; gap: 20px; position: relative; z-index: 1;\">\n        <div style=\"width: 40px; height: 40px; border-radius: 10px; background: rgba(255,255,255,0.1); border: 1px solid rgba(255,255,255,0.18); display: flex; align-items: center; justify-content: center;\">\n            <svg width=\"20\" height=\"20\" fill=\"none\" stroke=\"white\" stroke-width=\"1.8\" viewBox=\"0 0 24 24\">\n                <path d=\"M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z\"></path>\n            </svg>\n        </div>\n        <div>\n            <div style=\"font-size: 20px; font-weight: 700; letter-spacing: -0.01em; line-height: 1.15;\">\n                Cheques Due Report\n            </div>\n        </div>\n    </div>\n\n    <div style=\"position: relative; z-index: 1; display: flex; align-items: center; gap: 10px; background: rgba(255,255,255,0.1); padding: 8px 15px; border-radius: 8px; border: 1px solid rgba(255,255,255,0.15);\">\n        <svg width=\"16\" height=\"16\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" viewBox=\"0 0 24 24\">\n            <rect x=\"3\" y=\"4\" width=\"18\" height=\"18\" rx=\"2\" ry=\"2\"></rect>\n            <line x1=\"16\" y1=\"2\" x2=\"16\" y2=\"6\"></line>\n            <line x1=\"8\" y1=\"2\" x2=\"8\" y2=\"6\"></line>\n            <line x1=\"3\" y1=\"10\" x2=\"21\" y2=\"10\"></line>\n        </svg>\n        <span id=\"currentDate\" style=\"font-size: 0.9rem; font-weight: 500;\"></span>\n    </div>\n\n    <div style=\"position: absolute; bottom: 0; left: 0; right: 0; height: 5px; background: linear-gradient(90deg, #e8631a 0%, #f07a35 40%, #e8631a 100%);\"></div>\n</div>\n\n<script>\n    const options = { day: 'numeric', month: 'long', year: 'numeric' };\n    document.getElementById('currentDate').textContent = new Date().toLocaleDateString('en-GB', options);\n</script>",
