        "kind": "html",
        "table": null,
        "pk": null,
        "html": "<div class=\"gp\" id=\"cdApp\">\n  <section class=\"gp-hero\">\n    <div><span class=\"gp-eye\"><i></i>Cheques wallet &middot; Batch</span><h1 id=\"cdTitle\">Batch</h1><div class=\"cd-hero-st\" id=\"cdHeroSt\"></div></div>\n    <div class=\"gp-act\" id=\"cdActs\"></div>\n  </section>\n  <div class=\"cq-steps\" id=\"cqSteps\">\n    <div class=\"cq-step done\" data-s=\"1\"><i>1</i><div><b>Excel file chosen</b><span>Uploaded on the upload page.</span></div></div>\n    <div class=\"cq-step done\" data-s=\"2\"><i>2</i><div><b>Automatic checks</b><span>Customer, banks, empty cells, duplicates.</span></div></div>\n    <div class=\"cq-step done\" data-s=\"3\"><i>3</i><div><b>Batch created</b><span>Lines loaded and validated.</span></div></div>\n    <div class=\"cq-step\" data-s=\"4\"><i>4</i><div><b>Submit to the wallet</b><span>The cheques enter the client wallet.</span></div></div>\n  </div>\n  <div class=\"cd-next\" id=\"cdNext\"></div>\n  <div class=\"cd-kpis\" id=\"cdKpis\"></div>\n  <div class=\"cd-lay\">\n    <section class=\"cq-card\" id=\"cdHead\"><div class=\"cb-empty\">Loading&hellip;</div></section>\n    <section class=\"cq-card\"><div class=\"cd-lh\"><h2>Cheque lines</h2><div class=\"cd-chips\" id=\"cdChips\"></div></div><div id=\"cdLines\"></div></section>\n  </div>\n</div>\n<div class=\"cq-mb\" id=\"cqLoad\" aria-hidden=\"true\"><div class=\"cq-m\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"cqLt\">\n  <div class=\"cq-lh\"><svg viewBox=\"0 0 560 178\" preserveAspectRatio=\"xMidYMid meet\" aria-hidden=\"true\"><defs><linearGradient id=\"cqBeam\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\"><stop offset=\"0\" stop-color=\"#2BD4A8\" stop-opacity=\"0\"/><stop offset=\".5\" stop-color=\"#2BD4A8\" stop-opacity=\".55\"/><stop offset=\"1\" stop-color=\"#2BD4A8\" stop-opacity=\"0\"/></linearGradient><clipPath id=\"cqClip\"><rect x=\"150\" y=\"34\" width=\"112\" height=\"112\" rx=\"8\"/></clipPath></defs><rect x=\"150\" y=\"34\" width=\"112\" height=\"112\" rx=\"8\" class=\"cq-sheet\"/><rect x=\"150\" y=\"34\" width=\"112\" height=\"20\" rx=\"8\" class=\"cq-sh-hd\"/><rect x=\"150\" y=\"46\" width=\"112\" height=\"8\" class=\"cq-sh-hd\"/><text x=\"162\" y=\"48.5\" fill=\"#fff\" font-size=\"10\" font-weight=\"800\" font-family=\"Inter,Arial\">XLSX</text><rect x=\"158\" y=\"62\" width=\"96\" height=\"10\" rx=\"2\" class=\"cq-sh-row\"/><rect x=\"158\" y=\"78\" width=\"96\" height=\"10\" rx=\"2\" class=\"cq-sh-row\"/><rect x=\"158\" y=\"94\" width=\"96\" height=\"10\" rx=\"2\" class=\"cq-sh-row\"/><rect x=\"158\" y=\"110\" width=\"96\" height=\"10\" rx=\"2\" class=\"cq-sh-row\"/><rect x=\"158\" y=\"126\" width=\"96\" height=\"10\" rx=\"2\" class=\"cq-sh-row\"/><path d=\"M182 58v84M214 58v84\" class=\"cq-sh-ln\"/><g clip-path=\"url(#cqClip)\"><rect x=\"150\" y=\"30\" width=\"112\" height=\"30\" class=\"cq-beam\"/></g><g class=\"cq-fly \" style=\"transform-box:view-box;transform-origin:206px 90px\"><g transform=\"translate(206 90)\"><rect x=\"-15\" y=\"-9\" width=\"30\" height=\"18\" rx=\"3\" class=\"cq-chq\"/><path d=\"M-10 -3h11M-10 3h7M5 3h6\" class=\"cq-chql\"/></g></g><g class=\"cq-fly d2\" style=\"transform-box:view-box;transform-origin:206px 90px\"><g transform=\"translate(206 90)\"><rect x=\"-15\" y=\"-9\" width=\"30\" height=\"18\" rx=\"3\" class=\"cq-chq\"/><path d=\"M-10 -3h11M-10 3h7M5 3h6\" class=\"cq-chql\"/></g></g><g class=\"cq-fly d3\" style=\"transform-box:view-box;transform-origin:206px 90px\"><g transform=\"translate(206 90)\"><rect x=\"-15\" y=\"-9\" width=\"30\" height=\"18\" rx=\"3\" class=\"cq-chq\"/><path d=\"M-10 -3h11M-10 3h7M5 3h6\" class=\"cq-chql\"/></g></g><g class=\"cq-wb\"><rect x=\"372\" y=\"62\" width=\"88\" height=\"62\" rx=\"10\" class=\"cq-wal\"/><rect x=\"372\" y=\"56\" width=\"74\" height=\"16\" rx=\"6\" class=\"cq-wal2\"/><rect x=\"430\" y=\"82\" width=\"34\" height=\"22\" rx=\"6\" class=\"cq-wal2\"/><circle cx=\"444\" cy=\"93\" r=\"4\" class=\"cq-walbt\"/></g><text x=\"416\" y=\"146\" text-anchor=\"middle\" fill=\"rgba(255,255,255,.7)\" font-size=\"11\" font-family=\"Inter,Arial\">Client wallet</text><text x=\"206\" y=\"166\" text-anchor=\"middle\" fill=\"rgba(255,255,255,.7)\" font-size=\"11\" font-family=\"Inter,Arial\">Batch</text></svg></div>\n  <div class=\"cq-lbody\"><h3 id=\"cqLt\"></h3><p id=\"cqLf\"></p><ul class=\"cq-ls\" id=\"cqLs\"></ul><div class=\"cq-bar\"><i id=\"cqBar\"></i></div></div>\n</div></div>\n<div class=\"cq-mb\" id=\"cqRes\" aria-hidden=\"true\"><div class=\"cq-m wide\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"cqRt\">\n  <div class=\"cq-rh\"><span class=\"big\" id=\"cqRbig\"></span><div class=\"grow\"><h3 id=\"cqRt\"></h3><p id=\"cqRs\"></p></div><button type=\"button\" class=\"gp-x\" id=\"cqRx\" aria-label=\"Close\">&times;</button></div>\n  <div class=\"cq-rbody\"><div class=\"gp-err\" id=\"cqRerr\"></div><div id=\"cqRc\"></div></div>\n  <div class=\"cq-mf\" id=\"cqRf\"></div>\n</div></div>",
